    /**
     * Method to retrieve the Laboratory via LaboratoryFetchOneSummary
     * @param 	summary LaboratoryFetchOneSummary 
     * @return 	LaboratoryFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Laboratory getLaboratory( LaboratoryFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "LaboratoryFetchOneSummary arg cannot be null" );
    	
    	Laboratory entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Laboratory
        	// --------------------------------------
        	CompletableFuture<Laboratory> futureEntity = queryGateway.query(new FindLaboratoryQuery( new LoadLaboratoryFilter( summary.getLaboratoryId() ) ), ResponseTypes.instanceOf(Laboratory.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Laboratory with id " + summary.getLaboratoryId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


